import{_ as i,k as a,a6 as t,j as s}from"./chunks/framework.W_BvR9CP.js";const g=JSON.parse('{"title":"v1.34.0","description":"The changelog for v1.34.0.","frontmatter":{"title":"v1.34.0","page_title":"v1.34.0 Changelog","description":"The changelog for v1.34.0.","category":"Releases","mentions":["Andexter8"]},"headers":[{"level":2,"title":"Additions","slug":"additions","link":"#additions","children":[{"level":3,"title":"UIs","slug":"uis","link":"#uis","children":[]}]},{"level":2,"title":"Changes","slug":"changes","link":"#changes","children":[{"level":3,"title":"UIs","slug":"uis-1","link":"#uis-1","children":[]}]},{"level":2,"title":"Fixes","slug":"fixes","link":"#fixes","children":[{"level":3,"title":"Notifications","slug":"notifications","link":"#notifications","children":[]},{"level":3,"title":"Settings","slug":"settings","link":"#settings","children":[]}]},{"level":2,"title":"Technical Removals","slug":"technical-removals","link":"#technical-removals","children":[{"level":3,"title":"Events","slug":"events","link":"#events","children":[]}]},{"level":2,"title":"Technical Fixes","slug":"technical-fixes","link":"#technical-fixes","children":[]}],"relativePath":"changelogs/v1.34.0.md","filePath":"changelogs/v1.34.0.md"}'),l={name:"changelogs/v1.34.0.md"};function n(o,e,h,r,d,c){return s(),a("div",null,e[0]||(e[0]=[t('<p><strong>Updated the add-on to 1.21.70!</strong></p><h2 id="additions" tabindex="-1">Additions <a class="header-anchor" href="#additions" aria-label="Permalink to &quot;Additions&quot;">​</a></h2><h3 id="uis" tabindex="-1">UIs <a class="header-anchor" href="#uis" aria-label="Permalink to &quot;UIs&quot;">​</a></h3><ul><li>Added the following new pieces of information to the &quot;Debug Info&quot; section of the debug settings menu: <ul><li>&quot;Entity Count&quot;</li><li>&quot;Player Count&quot;</li><li>&quot;Weather&quot;</li><li>&quot;Difficulty&quot;</li><li>&quot;Is Hardcore&quot;</li><li>&quot;Is Editor World&quot;</li><li>&quot;Add-On Version&quot;</li><li>&quot;Entity Scale Version&quot;</li><li>&quot;BlueMods Anticheat Version&quot;</li><li>&quot;Server Timezone&quot;</li></ul></li></ul><h2 id="changes" tabindex="-1">Changes <a class="header-anchor" href="#changes" aria-label="Permalink to &quot;Changes&quot;">​</a></h2><h3 id="uis-1" tabindex="-1">UIs <a class="header-anchor" href="#uis-1" aria-label="Permalink to &quot;UIs&quot;">​</a></h3><ul><li>Updated the &quot;Debug Info&quot; section of the debug settings menu to be the fullscreen form size instead of the medium form size.</li><li>Updated the &quot;Raw Config&quot; section of the debug settings menu to be the fullscreen form size instead of the medium form size.</li><li>Updated the &quot;Anti-Spam Settings&quot; menu to be the medium form size instead of vanilla.</li><li>Updated the &quot;Home System Settings&quot; menu to be the medium form size instead of vanilla.</li></ul><h2 id="fixes" tabindex="-1">Fixes <a class="header-anchor" href="#fixes" aria-label="Permalink to &quot;Fixes&quot;">​</a></h2><h3 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h3><ul><li>Fixed a bug where the player dimension change notifications has the to and from dimensions and locations reversed.</li></ul><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><ul><li>Fixed a bug where the <code class="shiki"><span>useLegacyPlayerInventoryDataSaveSystem</span></code> setting would say it needed a restart to change when the general settings were saved, even if the setting was not changed.</li><li>Fixed a bug where the <code class="shiki"><span>playerInventoryDataSaveSystemEnabled</span></code> and <code class="shiki"><span>useLegacyPlayerInventoryDataSaveSystem</span></code> setttings didn&#39;t say that they needed a restart when the general settings were saved, even if the setting was changed.</li><li>Fixed a bug where the <code class="shiki"><span>Name Tags Rank Evaluator Mode</span></code> setting in the general name tags settings menu was display the current value of <a href="https://api.8crafter.com/andexdb/v1.34.0/classes/Globals.config.chatRanks.html#rankevaluatormode_chat" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">config</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">chatRanks</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">rankEvaluatorMode_chat</span></code></a> instead of <a href="https://api.8crafter.com/andexdb/v1.34.0/classes/Globals.config.chatRanks.html#rankevaluatormode_nameTAgs" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">config</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">chatRanks</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">rankEvaluatorMode_nameTags</span></code></a>.</li></ul><h2 id="technical-removals" tabindex="-1">Technical Removals <a class="header-anchor" href="#technical-removals" aria-label="Permalink to &quot;Technical Removals&quot;">​</a></h2><h3 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h3><ul><li>Removed everything related to the <code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">ItemUseOn</span></code> events. Note: the <code class="shiki"><span>itemUseOnCode</span></code> dynamic property of an item stack will still be evaluated, but from the <code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">PlayerInteractWithBlock</span></code> events instead.</li><li>Removed the <code class="shiki"><span>evalBeforeEvents:worldInitialize</span></code> property.</li></ul><h2 id="technical-fixes" tabindex="-1">Technical Fixes <a class="header-anchor" href="#technical-fixes" aria-label="Permalink to &quot;Technical Fixes&quot;">​</a></h2><ul><li>Fixed a bug where <a href="https://api.8crafter.com/andexdb/v1.34.0/classes/Globals.config.html#tojson" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">config</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">toJSON</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">()</span></code></a> threw a stack overflow error.</li></ul>',17)]))}const k=i(l,[["render",n]]);export{g as __pageData,k as default};
